UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"therapeutic_class":"Cardiologia / Anti-hipertensivo e Nefrorprotetor","pharmacological_class":"Inibidor da Enzima Conversora de Angiotensina (IECA)","formulations":[{"presentation":"Formulação farmacêutica padronizada conforme registro Anvisa","dose_text":"Dose diária inicial titulada conforme tolerância hemodinâmica","interval_text":"12/12 horas (enalapril) ou 8/8 horas (captopril) ou 24/24 horas (ramipril)","route":"Via oral","duration_text":"Conforme prescrição médica e evolução clínica","max_daily_text":"Não ultrapassar a dose máxima descrita na bula do fabricante","administration":"Administrar com água, observando a relação com as refeições conforme bula.","cautions":"Monitorar resposta terapêutica, adesão e sinais de hipersensibilidade.","prescription_type":"Receita Simples"}],"contraindications":["Histórico de angioedema prévio associado a IECA, estenose bilateral da artéria renal, e gravidez (teratogênico)."],"renal_adjustment":"Reduzir dose se ClCr < 30 mL/min; monitorar creatinina e potássio sérico (risco de hipercalemia).","hepatic_adjustment":"Ajuste geralmente não necessário; pró-fármacos dependem de hidrólise hepática.","adverse_reactions":["Tosse seca persistente (mediada por bradicinina), hipercalemia, hipotensão postural e tontura."],"drug_interactions":["Suplementos de potássio e poupadores de potássio (espironolactona) aumentam risco de hipercalemia grave."],"clinical_fields_complete":true,"catalog_only":false,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
