UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"therapeutic_class":"Psiquiatria / Ansiolítico e Sedativo","pharmacological_class":"Benzodiazepínico (modulador alostérico positivo de GABA-A)","formulations":[{"presentation":"Formulação farmacêutica padronizada conforme registro Anvisa","dose_text":"Dose titulada individualmente iniciando pela menor dose eficaz","interval_text":"8/8 horas, 12/12 horas ou dose única noturna","route":"Via oral","duration_text":"Uso a curto prazo (máximo de 2 a 4 semanas com desmame gradual)","max_daily_text":"Não ultrapassar a dose máxima descrita na bula do fabricante","administration":"Administrar com água, observando a relação com as refeições conforme bula.","cautions":"Monitorar resposta terapêutica, adesão e sinais de hipersensibilidade.","prescription_type":"Notificação de Receita B (Azul)"}],"contraindications":["Miastenia gravis, glaucoma de ângulo fechado não controlado, insuficiência respiratória grave e apneia do sono grave."],"renal_adjustment":"Usar doses menores; metabólitos ativos podem acumular em doença renal crônica.","hepatic_adjustment":"Contraindicado em insuficiência hepática grave (Child-Pugh C) devido ao risco de encefalopatia hepática.","adverse_reactions":["Sonolência diurna, ataxia, lentificação psicomotora, déficit de memória anterógrada, tolerância e dependência."],"drug_interactions":["Potencialização depressora respiratória severa e risco de óbito quando associado a opioides ou álcool."],"clinical_fields_complete":true,"catalog_only":false,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
