UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"therapeutic_class":"Gastroenterologia / Antissecretor Gástrico","pharmacological_class":"Inibidor da Bomba de Prótons (IBP)","formulations":[{"presentation":"Formulação farmacêutica padronizada conforme registro Anvisa","dose_text":"20 mg a 40 mg","interval_text":"24/24 horas (em jejum, 30 minutos antes do café da manhã)","route":"Via oral","duration_text":"4 a 8 semanas conforme cicatrização de mucosa","max_daily_text":"Não ultrapassar a dose máxima descrita na bula do fabricante","administration":"Ingerir em jejum pela manhã com um copo de água, 30 minutos antes da primeira refeição.","cautions":"Monitorar resposta terapêutica, adesão e sinais de hipersensibilidade.","prescription_type":"Receita Simples"}],"contraindications":["Hipersensibilidade conhecida a benzimidazois substituídos."],"renal_adjustment":"Sem necessidade de ajuste posológico em disfunção renal.","hepatic_adjustment":"Em insuficiência hepática grave, dose máxima recomendada de 20 mg/dia.","adverse_reactions":["Cefaleia, diarreia, dor abdominal, náuseas e hipomagnesemia em uso prolongado."],"drug_interactions":["Monitorar associações com outros fármacos de metabolismo hepático (CYP450) ou eliminação renal concorrente.","Consultar interações específicas na presença de anticoagulantes ou depressores do sistema nervoso central."],"clinical_fields_complete":true,"catalog_only":false,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
